headers -> {
    headers.remove(X_GSCLOUD_USERNAME);
    headers.remove(X_GSCLOUD_ROLES);
    if (StringUtils.hasText(username)) {
        List<String> sessionRoles = roles != null ? roles : List.of();
        headers.set(X_GSCLOUD_USERNAME, username);
        sessionRoles.forEach(role -> headers.add(X_GSCLOUD_ROLES, role));
        if (log.isDebugEnabled()) {
            log.debug("appended shared-auth request headers from session[{}] {}: {}, {}: {} to {} {}", session.getId(), X_GSCLOUD_USERNAME, urlEncode(username), X_GSCLOUD_ROLES, concatRoleNames(sessionRoles), sanitizeMethod(request.method()), sanitizeUri(String.valueOf(request.uri())));
        }
    } else if (log.isTraceEnabled()) {
        log.trace("{} from session is '{}', not appending shared-auth headers to {} {}", X_GSCLOUD_USERNAME, urlEncode(username), sanitizeMethod(request.method()), sanitizeUri(String.valueOf(request.uri())));
    }
}

